// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { OApp, MessagingFee, Origin } from "@layerzerolabs/oapp-evm/contracts/oapp/OApp.sol";
import { MessagingReceipt } from "@layerzerolabs/oapp-evm/contracts/oapp/OAppSender.sol";
import { OAppOptionsType3 } from "@layerzerolabs/oapp-evm/contracts/oapp/libs/OAppOptionsType3.sol";
import "./RegistrarStorageChild.sol";

contract MessagingContract is OApp, OAppOptionsType3 {
    RegistrarStorage public immutable registrarStorage;
    constructor(
        address _registrarStorage,
        address _endpoint,
        address _delegate
    ) OApp(_endpoint, _delegate) Ownable(_delegate) {
        registrarStorage = RegistrarStorage(_registrarStorage);
    }

    function sendVerificationRequest(
        string memory operation,
        bytes memory data,
        bytes memory signature,
        bytes memory operationData,
        uint32 dstEid,
        bytes calldata options
    ) external payable returns (MessagingReceipt memory receipt) {
        bytes memory payload;
        bytes32 operationHash = keccak256(bytes(operation));

        // Special handling for addSecondaryAddress due to combined payload
        if (operationHash == keccak256("addSecondaryAddress")) {
            payload = data; // Use the combined payload directly
        } else {
            payload = abi.encode(operation, data, signature, operationData);
        }

        receipt = _lzSend(dstEid, payload, options, MessagingFee(msg.value, 0), payable(msg.sender));
    }

    function _lzReceive(
        Origin calldata /*_origin*/,
        bytes32 /*_guid*/,
        bytes calldata payload,
        address /*_executor*/,
        bytes calldata /*_extraData*/
    ) internal override {
        string memory operation;
        bytes memory operationData;
        bool isValid;

        // Decode based on operation type
        bytes32 operationHash = keccak256(abi.encodePacked(payload[0:32])); // Rough check for operation
        if (operationHash == keccak256("addSecondaryAddress")) {
            (, , , bytes memory opData) = abi.decode(payload, (bytes, bytes, bytes, bytes));
            operation = "addSecondaryAddress";
            operationData = opData;
            isValid = true; // Assuming verification passed from VerificationContract
        } else {
            (operation, operationData, isValid) = abi.decode(payload, (string, bytes, bool));
        }

        if (!isValid) return;

        operationHash = keccak256(bytes(operation));
        if (operationHash == keccak256("registerSafleId")) {
            (string memory _safleId, address _primaryAddress) = abi.decode(operationData, (string, address));
            registrarStorage.completeRegisterSafleId(_safleId, _primaryAddress);
        } else if (operationHash == keccak256("updateSafleId")) {
            (string memory _oldSafleId, string memory _newSafleId) = abi.decode(operationData, (string, string));
            registrarStorage.completeUpdateSafleId(_oldSafleId, _newSafleId);
        } else if (operationHash == keccak256("updateSafleIdPrimaryAddress")) {
            (string memory _safleId, address _newPrimaryAddress) = abi.decode(operationData, (string, address));
            registrarStorage.completeUpdateSafleIdPrimaryAddress(_safleId, _newPrimaryAddress);
        } else if (operationHash == keccak256("addSecondaryAddress")) {
            (string memory _safleId, address _secondaryAddress) = abi.decode(operationData, (string, address));
            registrarStorage.completeAddSecondaryAddress(_safleId, _secondaryAddress);
        } else if (operationHash == keccak256("removeSecondaryAddress")) {
            (string memory _safleId, address _secondaryAddress) = abi.decode(operationData, (string, address));
            registrarStorage.completeRemoveSecondaryAddress(_safleId, _secondaryAddress);
        }
    }
}

contracts/RegistrarStorageChild.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./RegistrarStorageUtil.sol";
import "./MessagingContract.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

contract RegistrarStorage is UUPSUpgradeable, OwnableUpgradeable {
    struct UserData {
        address primary;
        mapping(address => bool) isSecondary;
        address[] secondaries;
        bool exists;
    }
    struct Registrar {
        bool isRegisteredRegistrar;
        string registrarName;
        address registrarAddress;
    }

    uint256 public registrarFees;
    uint256 public safleIdFees;
    address public contractOwner;
    address payable public walletAddress;
    uint256 public MAX_NAME_UPDATES;
    bool public isPaused;
    uint256 public totalRegistrars;
    uint256 public totalSafleIdRegistered;
    RegistrarStorageUtil public util;
    MessagingContract public messagingContract;

    // Registrar-related mappings
    mapping(address => bool) public isRegisteredRegistrar;
    mapping(address => string) public registrarNames;
    mapping(string => address) public registrarNameToAddress;
    mapping(address => uint8) public totalRegistrarUpdates;
    mapping(address => bytes[]) public resolveOldRegistrarAddress;
    mapping(address => Registrar) public Registrars;

    // User and SafleID mappings
    mapping(string => UserData) private userAddresses;
    mapping(string => bool) public unavailableSafleIds;
    string[] public registeredSafleIds;

    // Mappings to manage the SafleID functionalities
    mapping(bytes => address) public resolveAddressFromSafleId;
    mapping(address => bool) public isAddressTaken;
    mapping(address => string) public resolveSafleIdfromAddress;

    // Events
    event SecondaryAddressAdded(string indexed safleId, address secondary);
    event SecondaryAddressRemoved(string indexed safleId, address secondary);
    event RegistrarRegistered(address indexed registrar, string registrarName);
    event RegistrarUpdated(address indexed registrar, string oldName, string newName);
    event RegistrationPaused(address indexed by);
    event RegistrationUnpaused(address indexed by);
    event SafleIDRegistered(string indexed safleId, address primary);
    event SafleIDUpdated(string indexed safleId, address oldPrimary, address newPrimary);
    event TokenAllowed(address indexed token);
    event TokenDisallowed(address indexed token);
    event SafleIDChanged(string indexed oldSafleId, string indexed newSafleId, address primary);

    // Modifiers
    modifier safleIdExists(string memory _safleId) {
        require(userAddresses[_safleId].exists, "SafleID does not exist");
        _;
    }
    modifier WhenNotPaused() {
        require(!isPaused, "Contract is Paused");
        _;
    }
    modifier safleIdDoesNotExist(string memory _safleId) {
        require(!userAddresses[_safleId].exists, "SafleID already exists");
        require(!unavailableSafleIds[_safleId], "SafleID not available");
        _;
    }
    modifier registrarChecks(string memory _registrarName) {
        bytes memory regNameBytes = bytes(_registrarName);
        require(registrarNameToAddress[string(regNameBytes)] == address(0x0), "Registrar name is already taken.");
        require(
            resolveAddressFromSafleId[regNameBytes] == address(0x0),
            "This Registrar name is already registered as a SafleID."
        );
        _;
    }
    modifier onlyMessagingContract() {
        require(msg.sender == address(messagingContract), "Only messaging contract can call");
        _;
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // **Initialization**
    function initialize(address payable _walletAddress, address _RegistrarStorageUtil) public initializer {
        __Ownable_init(msg.sender);
        __UUPSUpgradeable_init();
        MAX_NAME_UPDATES = 3;
        walletAddress = _walletAddress;
        registrarFees = 0;
        safleIdFees = 0;
        util = RegistrarStorageUtil(_RegistrarStorageUtil);
    }

    // **Owner Functions**
    function setSafleIdFees(uint256 _amount) public WhenNotPaused onlyOwner {
        require(_amount >= 0, "Please set a fee for SafleID registration.");
        safleIdFees = _amount;
    }
    function setRegistrarFees(uint256 _amount) public WhenNotPaused onlyOwner {
        require(_amount >= 0, "Please set a fee for Registrar registration.");
        registrarFees = _amount;
    }
    function updateWalletAddress(address payable _walletAddress) public WhenNotPaused onlyOwner {
        require(!util.isContract(_walletAddress), "Wallet address cannot be a contract");
        walletAddress = _walletAddress;
    }
    function setUtilImplementation(address _RegistrarStorageUtil) external onlyOwner {
        util = RegistrarStorageUtil(_RegistrarStorageUtil);
    }
    function setMessagingContract(address _messagingContract) external onlyOwner {
        messagingContract = MessagingContract(_messagingContract);
    }
    function getRequiredTokenAmount(address token) public view returns (uint256) {
        return util.getRequiredTokenAmount(token, registrarFees);
    }

    // **Registrar Functions**
    function registerRegistrar(
        string calldata _registrarName,
        address _token
    ) external payable WhenNotPaused registrarChecks(_registrarName) returns (bool) {
        require(!isAddressTaken[msg.sender], "This address is already registered.");
        uint256 requiredAmount = getRequiredTokenAmount(_token);
        if (_token == address(0)) {
            require(msg.value >= requiredAmount, "Registration fees not matched.");
            walletAddress.transfer(msg.value);
        } else {
            IERC20(_token).transferFrom(msg.sender, walletAddress, requiredAmount);
        }
        Registrars[msg.sender] = Registrar({
            isRegisteredRegistrar: true,
            registrarName: _registrarName,
            registrarAddress: msg.sender
        });
        registrarNameToAddress[_registrarName] = msg.sender;
        registrarNames[msg.sender] = _registrarName;
        isRegisteredRegistrar[msg.sender] = true;
        isAddressTaken[msg.sender] = true;
        totalRegistrars++;
        emit RegistrarRegistered(msg.sender, _registrarName);
        return true;
    }

    function updateRegistrar(
        address _registrar,
        string calldata _newRegistrarName
    ) external WhenNotPaused registrarChecks(_newRegistrarName) returns (bool) {
        require(isAddressTaken[_registrar], "Registrar should register first.");
        require(totalRegistrarUpdates[_registrar] + 1 <= MAX_NAME_UPDATES, "Maximum update count reached.");
        Registrar storage registrarObject = Registrars[_registrar];
        string memory oldName = registrarObject.registrarName;
        registrarNameToAddress[oldName] = address(0x0);
        resolveOldRegistrarAddress[_registrar].push(bytes(registrarObject.registrarName));
        registrarNames[_registrar] = _newRegistrarName;
        registrarObject.registrarName = _newRegistrarName;
        registrarNameToAddress[_newRegistrarName] = _registrar;
        totalRegistrarUpdates[_registrar]++;
        emit RegistrarUpdated(_registrar, oldName, _newRegistrarName);
        return true;
    }

    function PauseRegistration() external onlyOwner {
        isPaused = true;
        emit RegistrationPaused(msg.sender);
    }
    function unPauseRegistration() external onlyOwner {
        isPaused = false;
        emit RegistrationUnpaused(msg.sender);
    }

    // **SafleID Functions with Cross-Chain Verification**

    // **registerSafleId**
    function initiateRegisterSafleId(
        string calldata _safleId,
        address _primaryAddress,
        bytes calldata _signature,
        address _token,
        uint32 _dstEid,
        bytes calldata _options
    ) external payable WhenNotPaused returns (bool) {
        require(util.isSafleIdValid(_safleId), "Invalid SafleId format");
        require(!userAddresses[_safleId].exists, "SafleID already exists");
        require(!unavailableSafleIds[_safleId], "SafleID not available");
        require(
            registrarNameToAddress[string(bytes(_safleId))] == address(0x0),
            "This SafleId is taken by a Registrar."
        );
        require(resolveAddressFromSafleId[bytes(_safleId)] == address(0x0), "This SafleId is already registered.");

        uint256 requiredAmount = getRequiredTokenAmount(_token);
        if (_token == address(0)) {
            require(msg.value >= requiredAmount, "Insufficient registration fees");
            walletAddress.transfer(requiredAmount);
            messagingContract.sendVerificationRequest{ value: msg.value - requiredAmount }(
                "registerSafleId",
                abi.encodePacked("registerSafleId", _safleId, _primaryAddress),
                _signature,
                abi.encode(_safleId, _primaryAddress),
                _dstEid,
                _options
            );
        } else {
            IERC20(_token).transferFrom(msg.sender, walletAddress, requiredAmount);
            messagingContract.sendVerificationRequest{ value: msg.value }(
                "registerSafleId",
                abi.encodePacked("registerSafleId", _safleId, _primaryAddress),
                _signature,
                abi.encode(_safleId, _primaryAddress),
                _dstEid,
                _options
            );
        }
        return true;
    }
    function completeRegisterSafleId(
        string memory _safleId,
        address _primaryAddress
    ) external onlyMessagingContract returns (bool) {
        UserData storage userData = userAddresses[_safleId];
        userData.primary = _primaryAddress;
        userData.exists = true;
        resolveAddressFromSafleId[bytes(_safleId)] = _primaryAddress;
        resolveSafleIdfromAddress[_primaryAddress] = _safleId;
        registeredSafleIds.push(_safleId);
        unavailableSafleIds[_safleId] = true;
        totalSafleIdRegistered++;
        emit SafleIDRegistered(_safleId, _primaryAddress);
        return true;
    }

    // **updateSafleId**
    function initiateUpdateSafleId(
        string calldata _oldSafleId,
        string calldata _newSafleId,
        bytes calldata _signature,
        address _token,
        uint32 _dstEid,
        bytes calldata _options
    ) external payable WhenNotPaused safleIdExists(_oldSafleId) safleIdDoesNotExist(_newSafleId) returns (bool) {
        require(util.isSafleIdValid(_newSafleId), "Invalid new SafleId format");
        UserData storage userData = userAddresses[_oldSafleId];

        uint256 requiredAmount = getRequiredTokenAmount(_token);
        if (_token == address(0)) {
            require(msg.value >= requiredAmount, "Insufficient update fees");
            walletAddress.transfer(requiredAmount);
            messagingContract.sendVerificationRequest{ value: msg.value - requiredAmount }(
                "updateSafleId",
                abi.encodePacked("updateSafleId", _oldSafleId, userData.primary),
                _signature,
                abi.encode(_oldSafleId, _newSafleId),
                _dstEid,
                _options
            );
        } else {
            IERC20(_token).transferFrom(msg.sender, walletAddress, requiredAmount);
            messagingContract.sendVerificationRequest{ value: msg.value }(
                "updateSafleId",
                abi.encodePacked("updateSafleId", _oldSafleId, userData.primary),
                _signature,
                abi.encode(_oldSafleId, _newSafleId),
                _dstEid,
                _options
            );
        }
        return true;
    }

    function completeUpdateSafleId(
        string memory _oldSafleId,
        string memory _newSafleId
    ) external onlyMessagingContract returns (bool) {
        UserData storage userData = userAddresses[_oldSafleId];
        resolveAddressFromSafleId[bytes(_newSafleId)] = userData.primary;
        resolveAddressFromSafleId[bytes(_oldSafleId)] = address(0);
        resolveSafleIdfromAddress[userData.primary] = _newSafleId;

        UserData storage newUserData = userAddresses[_newSafleId];
        newUserData.primary = userData.primary;
        newUserData.exists = true;

        for (uint i = 0; i < userData.secondaries.length; i++) {
            address secondaryAddr = userData.secondaries[i];
            newUserData.isSecondary[secondaryAddr] = true;
            newUserData.secondaries.push(secondaryAddr);
        }

        for (uint i = 0; i < registeredSafleIds.length; i++) {
            if (keccak256(bytes(registeredSafleIds[i])) == keccak256(bytes(_oldSafleId))) {
                registeredSafleIds[i] = _newSafleId;
                break;
            }
        }

        unavailableSafleIds[_oldSafleId] = true;
        unavailableSafleIds[_newSafleId] = true;
        delete userAddresses[_oldSafleId];
        emit SafleIDChanged(_oldSafleId, _newSafleId, userData.primary);
        return true;
    }

    // **updateSafleIdPrimaryAddress**
    function initiateUpdateSafleIdPrimaryAddress(
        string calldata _safleId,
        address _newPrimaryAddress,
        bytes calldata _signature,
        uint32 _dstEid,
        bytes calldata _options
    ) external payable WhenNotPaused safleIdExists(_safleId) returns (bool) {
        UserData storage userData = userAddresses[_safleId];
        messagingContract.sendVerificationRequest{ value: msg.value }(
            "updateSafleIdPrimaryAddress",
            abi.encodePacked("updateSafleIdPrimaryAddress", _safleId, userData.primary),
            _signature,
            abi.encode(_safleId, _newPrimaryAddress),
            _dstEid,
            _options
        );
        return true;
    }

    function completeUpdateSafleIdPrimaryAddress(
        string memory _safleId,
        address _newPrimaryAddress
    ) external onlyMessagingContract returns (bool) {
        UserData storage userData = userAddresses[_safleId];
        address oldPrimary = userData.primary;
        userData.primary = _newPrimaryAddress;
        resolveAddressFromSafleId[bytes(_safleId)] = _newPrimaryAddress;
        resolveSafleIdfromAddress[_newPrimaryAddress] = _safleId;
        resolveSafleIdfromAddress[oldPrimary] = "";
        emit SafleIDUpdated(_safleId, oldPrimary, _newPrimaryAddress);
        return true;
    }

    // **addSecondaryAddress**
    function initiateAddSecondaryAddress(
        string calldata _safleId,
        address _secondaryAddress,
        bytes calldata _primarySignature,
        bytes calldata _secondarySignature,
        uint32 _dstEid,
        bytes calldata _options
    ) external payable WhenNotPaused safleIdExists(_safleId) returns (bool) {
        UserData storage userData = userAddresses[_safleId];

        // Minimize local variables by encoding directly
        bytes memory primaryData = abi.encodePacked("addSecondaryAddress", _safleId, userData.primary);
        bytes memory secondaryData = abi.encodePacked("addSecondaryAddress", _safleId, _secondaryAddress);

        // Combine into a single payload to reduce stack slots
        bytes memory payload = abi.encode(
            primaryData,
            secondaryData,
            abi.encode(_primarySignature, _secondarySignature), // Combine signatures
            abi.encode(_safleId, _secondaryAddress) // Operation data
        );

        // Call messaging contract with the combined payload
        messagingContract.sendVerificationRequest{ value: msg.value }(
            "addSecondaryAddress",
            payload, // Use combined payload instead of separate data and signature
            "", // Empty signature field since it's in payload
            "", // Empty operationData field since it's in payload
            _dstEid,
            _options
        );
        return true;
    }

    function completeAddSecondaryAddress(
        string memory _safleId,
        address _secondaryAddress
    ) external onlyMessagingContract returns (bool) {
        UserData storage userData = userAddresses[_safleId];
        userData.isSecondary[_secondaryAddress] = true;
        userData.secondaries.push(_secondaryAddress);
        emit SecondaryAddressAdded(_safleId, _secondaryAddress);
        return true;
    }

    // **removeSecondaryAddress**
    function initiateRemoveSecondaryAddress(
        string calldata _safleId,
        address _secondaryAddress,
        bytes calldata _signature,
        uint32 _dstEid,
        bytes calldata _options
    ) external payable WhenNotPaused safleIdExists(_safleId) returns (bool) {
        UserData storage userData = userAddresses[_safleId];
        messagingContract.sendVerificationRequest{ value: msg.value }(
            "removeSecondaryAddress",
            abi.encodePacked("removeSecondaryAddress", _safleId, userData.primary),
            _signature,
            abi.encode(_safleId, _secondaryAddress),
            _dstEid,
            _options
        );
        return true;
    }

    function completeRemoveSecondaryAddress(
        string memory _safleId,
        address _secondaryAddress
    ) external onlyMessagingContract returns (bool) {
        UserData storage userData = userAddresses[_safleId];
        userData.isSecondary[_secondaryAddress] = false;
        for (uint i = 0; i < userData.secondaries.length; i++) {
            if (userData.secondaries[i] == _secondaryAddress) {
                userData.secondaries[i] = userData.secondaries[userData.secondaries.length - 1];
                userData.secondaries.pop();
                break;
            }
        }
        emit SecondaryAddressRemoved(_safleId, _secondaryAddress);
        return true;
    }

    // **View Functions**
    function isPrimaryAddress(string calldata _safleId, address _address) external view returns (bool) {
        return userAddresses[_safleId].primary == _address;
    }
    function isSecondaryAddress(string calldata _safleId, address _address) external view returns (bool) {
        return userAddresses[_safleId].isSecondary[_address];
    }
    function getPrimaryAddress(string calldata _safleId) external view returns (address) {
        return userAddresses[_safleId].primary;
    }
    function getSecondaryAddresses(string calldata _safleId) external view returns (address[] memory) {
        return userAddresses[_safleId].secondaries;
    }
    function getRegisteredSafleIds() external view returns (string[] memory) {
        return registeredSafleIds;
    }
}

contracts/RegistrarStorageUtil.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {AggregatorV3Interface} from "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";

contract RegistrarStorageUtil {
    mapping(address => address) public tokenPriceFeed;
    mapping(address => uint256) public tokenDecimal;
    address public ethPriceFeed;
    address public owner;
    string constant PREFIX = "\x19Ethereum Signed Message:\n32";
    
    // Events
    event TokenPriceFeedSet(address indexed token, address indexed priceFeed);
    event EthPriceFeedSet(address indexed priceFeed);
    event RegistrarStorageSet(address indexed newRegistrarStorage);
    
 
    constructor() {
        owner = msg.sender;      
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Caller is not the owner");
        _;
    }
    function setTokenPriceFeed(address token, address priceFeed, uint decimal) external onlyOwner {
        tokenPriceFeed[token] = priceFeed;
        tokenDecimal[token] = decimal;
        emit TokenPriceFeedSet(token, priceFeed);
    }

    // Set the ETH price feed address
    function setEthPriceFeed(address _ethPriceFeed) external onlyOwner {
        ethPriceFeed = _ethPriceFeed;
        emit EthPriceFeedSet(_ethPriceFeed);
    }

    // Get the required token amount based on the registrar fees
    function getRequiredTokenAmount(address token, uint256 registrarFees) external view returns (uint256) {
        if (token == address(0)) {
            return registrarFees;
        } else {
            uint256[] memory tokenInfo = getTokenAmount(token);
            uint256[] memory result = new uint256[](5);
            result[0] = tokenInfo[0]; // tokenPriceInUSD
            result[1] = tokenInfo[1]; // decimals
            result[2] = tokenInfo[2]; // ethPriceInUSD
            result[3] = tokenInfo[3]; // ethDecimals
            
            uint256 decimalAdjustment = 0;
            if (tokenInfo[1] != tokenInfo[3]) {
                if (tokenInfo[1] > tokenInfo[3]) {
                    decimalAdjustment = tokenInfo[1] - tokenInfo[3];
                    result[4] = (registrarFees * tokenInfo[2] * (10 ** decimalAdjustment)) / tokenInfo[0];
                } else {
                    decimalAdjustment = tokenInfo[3] - tokenInfo[1];
                    result[4] = (registrarFees * tokenInfo[2]) / (tokenInfo[0] * (10 ** decimalAdjustment));
                }
            } else {
                result[4] = (registrarFees * tokenInfo[2]) / tokenInfo[0];
            }
            
            return result[4] / 10 ** tokenDecimal[token];
        }
    }

    // Get token amount and price information
    function getTokenAmount(address token) public view returns (uint256[] memory) {
        AggregatorV3Interface priceFeed = AggregatorV3Interface(tokenPriceFeed[token]);
        (
            ,
            int answer,
            ,
            ,
        ) = priceFeed.latestRoundData();
        require(answer > 0, "Invalid token price");
        uint256 tokenPriceInUSD = uint256(answer);
        uint8 decimals = priceFeed.decimals();
        
        AggregatorV3Interface ethPriceAggregator = AggregatorV3Interface(ethPriceFeed);
        (
            ,
            int ethAnswer,
            ,
            ,
        ) = ethPriceAggregator.latestRoundData();
        require(ethAnswer > 0, "Invalid ETH price");
        uint256 ethPriceInUSD = uint256(ethAnswer);
        uint8 ethDecimals = ethPriceAggregator.decimals();
        
        uint256[] memory result = new uint256[](4);
        result[0] = tokenPriceInUSD;
        result[1] = decimals;
        result[2] = ethPriceInUSD;
        result[3] = ethDecimals;
        
        return result;
    }

    function getMessageHash(bytes memory _data) public pure returns (bytes32) {
        return keccak256(_data);
    }

    function getEthSignedMessageHash(bytes32 _messageHash) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(PREFIX, _messageHash));
    }

    function recoverSigner(bytes32 _ethSignedMessageHash, bytes memory _signature) public pure returns (address) {
        require(_signature.length == 65, "Invalid signature length");
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(_signature, 32))
            s := mload(add(_signature, 64))
            v := byte(0, mload(add(_signature, 96)))
        }
        if (v < 27) {
            v += 27;
        }
        require(v == 27 || v == 28, "Invalid signature 'v' value");
        return ecrecover(_ethSignedMessageHash, v, r, s);
    }

    function verifySignature(
        bytes memory _data,
        address _expectedSigner,
        bytes memory _signature
    ) public pure returns (bool) {
        bytes32 messageHash = getMessageHash(_data);
        bytes32 ethSignedMessageHash = getEthSignedMessageHash(messageHash);
        address signer = recoverSigner(ethSignedMessageHash, _signature);
        return signer == _expectedSigner;
    }
        uint8 constant MAX_SAFLEID_LENGTH = 16;
    uint8 constant MIN_SAFLEID_LENGTH = 4;

    /**
    * @dev  check if address is of wallet or contract 
    * @param _resolverAddress address to check
    */
    function isContract(address _resolverAddress) 
    public view
    returns(bool)
    {
        uint32 size;
        assembly {
            size := extcodesize(_resolverAddress)
        }
        return (size > 0);
    }
    
    /**
    * @dev  convert a string to lower case 
    * @param str string to be converted
    */

    function toLower(string memory str) public pure returns (string memory) {
        bytes memory bStr = bytes(str);
        bytes memory bLower = new bytes(bStr.length);
        for (uint i = 0; i < bStr.length; i++) {
            // Uppercase character...
            if ((uint8(bStr[i]) >= 65) && (uint8(bStr[i]) <= 90)) {
                // So we add 32 to make it lowercase
                bLower[i] = bytes1(uint8(bStr[i]) + 32);
            } else {
                bLower[i] = bStr[i];
            }
        }
        return string(bLower);
    }
    

    /**
    * @dev  to check length of a string 
    * @param _name string length to be check
    */
    function checkLength(string memory _name) public pure returns (uint8){
        require(bytes(_name).length != 0, "Library : String passed is of zero length");
        return uint8(bytes(_name).length);
    }

    /**
    * @dev  to check if string contains alphanumeric or ASCII characters
    * @param safleId string to be checked
    */

    function checkAlphaNumericandASCII(string memory safleId) public pure returns (bool) {
        bytes memory b = bytes(safleId);
        
        for(uint i; i < b.length; i++) {
            bytes1 char = b[i];
            
            if(!(
                (char >= 0x30 && char <= 0x39) || // 0-9
                (char >= 0x61 && char <= 0x7A) || // a-z
                (char >= 0x41 && char <= 0x5A) || // A-Z
                (uint8(char) >= 32 && uint8(char) <= 126) // ASCII printable characters
            )) {
                return false;
            }
        }
        
        return true;
    }   
    
    function isSafleIdValid (string memory _registrarName) public pure returns (bool){
        
        string memory VNinLowerCase = toLower(_registrarName);
        uint8 length = checkLength(_registrarName);
        require(checkAlphaNumericandASCII(VNinLowerCase),"only alphanumeric allowed");
        require(length <= MAX_SAFLEID_LENGTH && length >= MIN_SAFLEID_LENGTH,"SafleId length should be between 4-16 characters");
        return true;

    }
}
